#!/usr/bin/env python3
"""Track C: prints the full report as markdown on stdout = generated summary (numbers pulled from heading.json) + the tables of assemble.py.
Usage: report.py [--summary]     (nothing is written except heading.json, refreshed by assemble.py)"""
import os, json, subprocess, sys
O = '/root/rasr-pairuav/outputs/supp/trackC'; tables = subprocess.run([sys.executable, '/root/rasr-pairuav/supp/trackC/assemble.py'], check=True, capture_output=True, text=True).stdout
H = json.load(open(f'{O}/heading.json')); cpu, ret, sens, real, sites = H['test_set'], H.get('site_disjoint_retraining'), H.get('photometric_sensitivity'), H.get('real_photographs'), H['sites']
p1 = lambda v: f'{100 * v:.1f}'; S = []; A = S.append
E = cpu['error_statistics']; e2 = E['two-network ensemble, fused a+b (Stage II)']; e1 = E['raw-view, fused a+b (Stage I)']; C2 = cpu['consequences']['Stage II']; C1 = cpu['consequences']['Stage I']
A('## 0. Summary\n')
A(f"1. **Size of the error.** On the {cpu['n_pairs']:,} test pairs the fused absolute heading of the source camera is off by {e2['mean']:.1f} deg on average (95 % CI [{e2['mean_ci'][0]:.1f}, {e2['mean_ci'][1]:.1f}]) and {e2['median']:.1f} deg in median for Stage II (two-network ensemble); Stage I (raw-view network): {e1['mean']:.1f} / {e1['median']:.1f} deg. The tail is heavy: P90 {e2['p90']:.1f} deg, P95 {e2['p95']:.1f} deg, {p1(e2['gt10'])} % of the pairs above 10 deg, {p1(e2['gt45'])} % above 45 deg, {p1(e2['gt90'])} % above 90 deg.")
cam, net, c0 = C2['camera frame (no heading needed)'], C2['ENU, learned heading'], C2['ENU, compass (true heading + N(0, 0 deg))']; fa = C2['failure_attribution']
A(f"2. **Cost in the pose output.** Stage II reaches SR_EPE@1m {p1(cam['sr_epe_1m'])} % (EPE median {cam['epe_med']:.2f} m) in the camera frame and {p1(net['sr_epe_1m'])} % ({net['epe_med']:.2f} m) in ENU with the learned heading; x / y MAE {cam['x_mae']:.2f} / {cam['y_mae']:.2f} m vs {net['x_mae']:.2f} / {net['y_mae']:.2f} m. Stage I: {p1(C1['camera frame (no heading needed)']['sr_epe_1m'])} % vs {p1(C1['ENU, learned heading']['sr_epe_1m'])} %. "
  f"{p1(fa['fixed_by_true_heading'])} % of the Stage II failures in ENU (EPE >= 1 m) succeed with the true heading. With a compass of 1 / 2 / 5 / 10 deg noise the ENU SR_EPE@1m is {p1(C2['ENU, compass (true heading + N(0, 1 deg))']['sr_epe_1m'])} / {p1(C2['ENU, compass (true heading + N(0, 2 deg))']['sr_epe_1m'])} / {p1(C2['ENU, compass (true heading + N(0, 5 deg))']['sr_epe_1m'])} / {p1(C2['ENU, compass (true heading + N(0, 10 deg))']['sr_epe_1m'])} %: the learned heading is worth a compass with roughly 3 deg of noise on this test set. SR_d@1m (Table 2) and all rotation metrics do not depend on the heading.")
fam = {r['bin']: r for r in cpu['by_site_training_buildings']}; dst = {r['bin']: r for r in cpu['by_distance_to_nearest_training_building']}; c = cpu['building_level_correlation']
A(f"3. **The accuracy is tied to nearby training buildings.** The test buildings are other buildings of the same campuses: the median test building is {c['m_to_nearest_train']['median']:.0f} m from a training building, less than one image footprint. Heading error (mean / median) by distance to the nearest training building: " + '; '.join(f"{k}: {v['heading_s2']['mean']:.1f} / {v['heading_s2']['median']:.1f} deg" for k, v in dst.items()) +
  f". By number of training buildings in the same site: " + '; '.join(f"{k}: {v['heading_s2']['mean']:.1f} / {v['heading_s2']['median']:.1f} deg (ENU SR_EPE@1m {p1(v['sr_epe_enu'])} %)" for k, v in fam.items()) + f". Building-level Spearman correlation between error and distance: {c['spearman_meanerr_vs_distance']:+.2f}. The camera-frame success rate is flat across these bins.")
if ret and 'raw-view | B site-disjoint' in ret['subsets']['held-out sites']:
    o = ret['subsets']['held-out sites']; a_, c_, b_ = o['raw-view | A archived'], o.get('raw-view | C size-matched control'), o['raw-view | B site-disjoint']; pr = o['paired']
    A(f"4. **Site-disjoint re-training.** With the {sites['train_buildings_removed']} training buildings of {len(sites['heldout_sites'])} held-out sites removed, the raw-view network evaluated on the {o['buildings']} test buildings of those sites ({o['pairs']} pairs) has a fused heading error of {b_['fused_heading']['mean']:.1f} deg mean / {b_['fused_heading']['median']:.1f} deg median, against {a_['fused_heading']['mean']:.1f} / {a_['fused_heading']['median']:.1f} deg for the archived network on the same pairs"
      + (f" and {c_['fused_heading']['mean']:.1f} / {c_['fused_heading']['median']:.1f} deg for the size-matched control (same amount of training data, site seen)" if c_ else '') +
      f". Stage II ENU SR_EPE@1m on those pairs: {p1(a_['sr_epe_1m'])} % (archived)" + (f", {p1(c_['sr_epe_1m'])} % (control)" if c_ else '') + f", {p1(b_['sr_epe_1m'])} % (site-disjoint); camera frame {p1(o['camera_frame']['sr_epe_1m'])} %. EPE median {a_['epe_med']:.2f} -> {b_['epe_med']:.2f} m."
      + (f" Paired difference site-disjoint minus control: heading mean {pr['raw-view | B site-disjoint minus raw-view | C size-matched control']['heading_mean']['delta']:+.1f} deg [{pr['raw-view | B site-disjoint minus raw-view | C size-matched control']['heading_mean']['ci'][0]:+.1f}, {pr['raw-view | B site-disjoint minus raw-view | C size-matched control']['heading_mean']['ci'][1]:+.1f}], SR_EPE@1m {100 * pr['raw-view | B site-disjoint minus raw-view | C size-matched control']['sr_epe_1m']['delta']:+.1f} points [{100 * pr['raw-view | B site-disjoint minus raw-view | C size-matched control']['sr_epe_1m']['ci'][0]:+.1f}, {100 * pr['raw-view | B site-disjoint minus raw-view | C size-matched control']['sr_epe_1m']['ci'][1]:+.1f}]." if c_ else ''))
    if 'ensemble | B site-disjoint' in o:
        eb, ea = o['ensemble | B site-disjoint'], o['ensemble | A archived']; A(f"   With both networks re-trained site-disjoint (the Stage II ensemble): heading {eb['fused_heading']['mean']:.1f} / {eb['fused_heading']['median']:.1f} deg (archived ensemble {ea['fused_heading']['mean']:.1f} / {ea['fused_heading']['median']:.1f}), ENU SR_EPE@1m {p1(eb['sr_epe_1m'])} % (archived {p1(ea['sr_epe_1m'])} %), EPE median {eb['epe_med']:.2f} m (archived {ea['epe_med']:.2f} m).")
    per = ret['heldout_per_site']; A('   Per held-out site (site-disjoint raw-view network; signed mean error, resultant length R): ' + '; '.join(f"site {r['site']} ({r['buildings']} bld.): {r['raw-view | B site-disjoint']['signed_circular_mean']:+.0f} deg, R {r['raw-view | B site-disjoint']['resultant_length']:.2f}, MAE {r['raw-view | B site-disjoint']['heading_mean']:.0f} deg" for r in per) + '.')
hs = {r['bin']: r for r in cpu['by_hemisphere']}
if 'south' in hs: A(f"5. **Sun direction.** On the {hs['south']['buildings']} southern-hemisphere test buildings ({hs['south']['pairs']} pairs; {sites['southern_hemisphere']['train']} such buildings in training) the heading error is {hs['south']['heading_s2']['mean']:.0f} deg (signed mean {cpu['southern_signed_error_circular_mean']:+.0f} deg) and the ENU success rate is {p1(hs['south']['sr_epe_enu'])} %, while the camera-frame success rate is {p1(hs['south']['sr_epe_cam'])} %.")
if sens:
    cd = sens['conditions']; g = lambda k: cd[k]['ensemble']
    def find(sub): return next(k for k in cd if sub in k)
    A(f"6. **Photometric sensitivity** ({sens['n_images']:,} test images, ensemble of the two networks, single image; clean MAE {g('clean')['mae']:.1f} / median {g('clean')['median']:.1f} deg). MAE under each perturbation: " + '; '.join(f"{k}: {cd[k]['ensemble']['mae']:.1f}" for k in cd if k != 'clean') + ' deg.'
      f" Inverting the intensities flips the prediction by 180 +- 30 deg for {p1(g(find('intensity inversion'))['flips_180_within_30deg'])} % of the images; shuffling 64-px tiles leaves the error at {g(find('64 px'))['mae']:.1f} deg.")
    if 'zoom_raw_view' in sens: z = sens['zoom_raw_view']; A('   Scale shift (raw-view network, centre zoom of the rendered image): ' + '; '.join(f"{k}: MAE {v['mae']:.1f} / median {v['median']:.1f} deg" for k, v in z.items()) + f" (clean {cd['clean']['raw-view']['mae']:.1f} / {cd['clean']['raw-view']['median']:.1f}).")
if real:
    r = real['single_image']; A(f"7. **Real photographs.** On the {real['photos']} Mezieres photographs the single-image heading error is MAE {r['raw-view']['all']['mae']:.0f} / median {r['raw-view']['all']['median']:.0f} deg (raw-view), {r['nadir-rectified']['all']['mae']:.0f} / {r['nadir-rectified']['all']['median']:.0f} deg (nadir-rectified), {r['ensemble']['all']['mae']:.0f} / {r['ensemble']['all']['median']:.0f} deg (ensemble); chance is 90 / 90."
      + (f" On the 300 pairs of Table 4, Stage II has EPE median {real['pairs']['within training range (300)']['Stage II']['epe_cam_median']:.2f} m in the camera frame (SR_EPE@1m {p1(real['pairs']['within training range (300)']['Stage II']['sr_epe_cam_1m'])} %) and {real['pairs']['within training range (300)']['Stage II']['epe_enu_median']:.2f} m in ENU with the learned heading (SR_EPE@1m {p1(real['pairs']['within training range (300)']['Stage II']['sr_epe_enu_1m'])} %); fused heading MAE {real['pairs']['within training range (300)']['Stage II']['fused_heading']['mae']:.0f} deg." if 'pairs' in real else ''))
rc = {r['coverage']: r for r in cpu['risk_coverage']['by_kappa']}
A(f"8. **Confidence.** The fused concentration kappa ranks the errors (Spearman {cpu['risk_coverage']['spearman_kappa_vs_error']:+.2f}): rejecting the 5 % / 10 % / 20 % least confident pairs lowers the heading MAE from {rc[1.0]['heading_mae']:.1f} to {rc[0.95]['heading_mae']:.1f} / {rc[0.9]['heading_mae']:.1f} / {rc[0.8]['heading_mae']:.1f} deg and the share of errors above 45 deg from {p1(rc[1.0]['heading_gt45'])} % to {100 * rc[0.95]['heading_gt45']:.2f} / {100 * rc[0.9]['heading_gt45']:.2f} / {100 * rc[0.8]['heading_gt45']:.2f} %; ENU SR_EPE@1m on the kept pairs: {p1(rc[0.95]['sr_epe_enu'])} / {p1(rc[0.9]['sr_epe_enu'])} / {p1(rc[0.8]['sr_epe_enu'])} %.")
head, rest = tables.split('## 1. Protocol', 1)
if '--summary' in sys.argv: print('\n'.join(S))
else: print(head + '\n'.join(S) + '\n\n## 1. Protocol' + rest)
